#ifndef FOLDING_CORRECTION_HH
#define FOLDING_CORRECTION_HH

#include <cstddef>
#include <limits>
#include <memory>
#include <string>
#include <vector>

namespace achilles {

class Cascade;
class Event;
class Nucleus;
class Particle;

/// Non-unitary final-state correction for the inclusive response (experimental). The folding
/// function of the eikonal formalism shifts and broadens the energy transfer; here the shift is
/// the real part of the nucleon potential at the vertex and the broadening is generated by the
/// cascade: the offset is drawn from the folding function of the configuration-averaged
/// amplitude <sqrt S(t)>, with S(t) the veto cascade's no-collision probability, and assigned by
/// the rank of the struck nucleon's first-collision time among the outcomes of its stratum (vertex
/// radius, momentum). Nucleons that escape without colliding get no broadening.
class FoldingCorrection {
  public:
    /// Full: offsets from the whole folding function. Limited: |Delta| kept inside the window
    /// that leaves the energy transfer physical (and below MaxDelta). Collided: as Limited, and
    /// |Delta| no larger than the energy the first collision took from the struck nucleon.
    /// Limits rescale the continuum of the folding function, the Delta = 0 atom is unchanged.
    enum class Mode { Full, Limited, Collided };
    static Mode ParseMode(const std::string &);

    explicit FoldingCorrection(Mode = Mode::Full,
                               double max_delta = std::numeric_limits<double>::infinity(),
                               std::size_t paths_per_bin = 8000, std::size_t npauli = 10);

    /// Shift the scattered lepton of an event whose single struck nucleon (index idx, state at
    /// the vertex primary) was evolved by the veto cascade; returns the applied offset [MeV]
    double Apply(Cascade &, Event &, std::size_t idx, const Particle &primary);

    /// Lower the outgoing lepton energy by the offset at fixed direction, in the event and in the
    /// primary vertex of its history; returns false (and leaves the event unchanged) if the
    /// lepton would fall below its mass
    static bool ShiftLepton(Event &, double offset);

  private:
    struct Ensemble {
        std::vector<double> survival, cumulative;
        double atom{}, transparency{}, n{};
    };
    void Build(Cascade &, const std::shared_ptr<Nucleus> &, bool proton, std::size_t pbin);
    const Ensemble *Table(Cascade &, const std::shared_ptr<Nucleus> &, const Particle &);
    double Delta(const Ensemble &, double t1, double delta_max) const;
    std::size_t Stratum(double radius) const;
    std::size_t Index(bool proton, std::size_t stratum, std::size_t pbin) const;
    double Quantile(const Ensemble &, double) const;
    double Cumulative(const Ensemble &, double delta) const;
    double Survival(const Ensemble &, double t) const;

    Mode m_mode;
    double m_max_delta;
    std::size_t m_paths, m_npauli;
    std::vector<double> m_radii, m_times, m_offsets;
    std::vector<Ensemble> m_ensembles;
    std::vector<bool> m_built;
};

} // namespace achilles

#endif
